-- Model: sat_erc_burdenvms_curr
-- Description: Current active record for SAT_ERC_BURDENVMS using ROW_NUMBER()
-- Generated by: bv pipeline generate transform with custom template
-- Satellite Type: SAT_ON_HUB
-- Parent: hub HUB_BURDENVMS

WITH RANKED_RECORDS AS (
SELECT
    BURDENVMS_HKEY,  -- hash key
    LOAD_DATE AS _CURRENT_ACTIVE_TIMESTAMP, -- used: LOAD_DATE
    -- Satellite Attributes
    VMSBURDENID            ,  -- is_business_key
    LOAD_DATE              ,  -- is_load_timestamp
    LOAD_CYCLE_ID          ,  -- is_load_cycle_id
    DELETE_FLAG            ,  -- is_delete_flag
    DEDUCTFORMARGIN        ,  -- is_other_attr
    DEDUCTFROMINVOICEAMOUNT,  -- is_other_attr
    ENTITYID               ,  -- is_other_attr
    HOURLYAMOUNT           ,  -- is_other_attr
    INCLUDEFORSALESTAX     ,  -- is_other_attr
    ISENABLED              ,  -- is_other_attr
    NAME                   ,  -- is_other_attr
    PERCENTAGEOFBILLED     ,  -- is_other_attr
    PERCENTAGEOFPAID       ,  -- is_other_attr
    _FIVETRAN_ACTIVE       ,  -- is_other_attr
    _FIVETRAN_END          ,  -- is_other_attr
    _FIVETRAN_START        ,  -- is_other_attr
    _FIVETRAN_TRANS           -- is_other_attr
    ,
    ROW_NUMBER() OVER (
        PARTITION BY BURDENVMS_HKEY
        ORDER BY LOAD_DATE DESC
    ) AS row_num
FROM {{ source('eli_dv_rv', 'sat_erc_burdenvms') }}
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RECORDS
WHERE row_num = 1
AND DELETE_FLAG = 'N'
